// frontend/src/pages/RestoreDB.js
// Restore database from any tier: Primary DB, Secondary DB, Remote Onsite, AWS S3, OCI

import { useState, useEffect, useCallback } from 'react';
import { destinationsAPI, regionsAPI } from '../services/api';
import { Btn, Modal, Field, Spinner, toast } from '../components/UI';

const r = (method, path, body) => {
  const token = localStorage.getItem('bv_token');
  return fetch('/api' + path, {
    method,
    headers: { 'Content-Type':'application/json', Authorization:'Bearer ' + token },
    body: body ? JSON.stringify(body) : undefined,
  }).then(async res => {
    const d = await res.json();
    if (!res.ok) throw new Error(d.error || 'HTTP ' + res.status);
    return d;
  });
};

function fmtBytes(b) {
  if (!b) return '—';
  const u = ['B','KB','MB','GB'];
  const i = Math.floor(Math.log(Math.max(b,1)) / Math.log(1024));
  return (b / Math.pow(1024, i)).toFixed(1) + ' ' + u[i];
}

function fmtDate(d) {
  if (!d) return '—';
  return new Date(d).toLocaleString('en-IN', {
    day:'2-digit', month:'short', year:'numeric',
    hour:'2-digit', minute:'2-digit'
  });
}

// ── TIER DEFINITIONS ──────────────────────────────────────────────────────────
const TIERS = [
  { key:'primary',   label:'Primary DB (NFS)',       icon:'server',    color:'var(--bv-green)',  desc:'Local NFS mount — fastest restore'        },
  { key:'secondary', label:'Secondary DB (NFS)',      icon:'database',  color:'var(--bv-cyan)',   desc:'Long-term archive — files >50 days'        },
  { key:'remote',    label:'Remote Onsite DR',        icon:'building',  color:'var(--bv-amber)',  desc:'192.168.12.243 — off-site copy'            },
  { key:'s3',        label:'AWS S3 Cloud',            icon:'brand-aws', color:'var(--bv-purple)', desc:'eu-west-2 — cloud backup'                  },
  { key:'oci',       label:'OCI Object Storage',      icon:'cloud',     color:'#c74634',          desc:'ap-mumbai-1 — AES-256-GCM encrypted'       },
];

// ── RESTORE STEPS ─────────────────────────────────────────────────────────────
const STEPS = ['Select Source', 'Select File', 'Target Server', 'Confirm & Restore'];

export default function RestoreDB() {
  const [step,        setStep]       = useState(0);
  const [tier,        setTier]       = useState(null);
  const [files,       setFiles]      = useState([]);
  const [loadingFiles,setLoadingFiles]= useState(false);
  const [selectedFile,setSelectedFile]= useState(null);
  const [dbServers,   setDbServers]  = useState([]);
  const [target,      setTarget]     = useState({ host:'', port:3306, user:'root', password:'', db_name:'', create_db:true, drop_existing:false });
  const [restoring,   setRestoring]  = useState(false);
  const [restoreLog,  setRestoreLog] = useState([]);
  const [done,        setDone]       = useState(false);

  // Load DB servers for restore target
  useEffect(() => {
    r('GET', '/targets').then(list => setDbServers(list || [])).catch(() => {});
  }, []);

  // Load files when tier selected
  const loadFiles = useCallback(async (tierKey) => {
    setLoadingFiles(true);
    setFiles([]);
    try {
      const list = await r('GET', '/restore/files?tier=' + tierKey);
      setFiles(list || []);
    } catch(e) { toast(e.message, 'error'); }
    finally { setLoadingFiles(false); }
  }, []);

  function selectTier(t) {
    setTier(t);
    setSelectedFile(null);
    setStep(1);
    loadFiles(t.key);
  }

  function selectFile(f) {
    setSelectedFile(f);
    setStep(2);
  }

  async function startRestore() {
    if (!selectedFile || !target.host || !target.db_name) {
      toast('Please fill all required fields', 'error');
      return;
    }
    setRestoring(true);
    setRestoreLog([]);
    setStep(3);
    setDone(false);

    const addLog = (level, msg) => setRestoreLog(p => [...p, { level, msg, time: new Date().toLocaleTimeString('en-IN') }]);

    try {
      addLog('INFO', 'Starting restore: ' + selectedFile.name);
      addLog('INFO', 'Source: ' + tier.label + ' → ' + selectedFile.path);
      addLog('INFO', 'Target: ' + target.host + ':' + target.port + '/' + target.db_name);

      const res = await r('POST', '/restore/run', {
        tier:           tier.key,
        file_path:      selectedFile.path,
        file_key:       selectedFile.key,
        dest_id:        selectedFile.dest_id,
        encrypted:      selectedFile.encrypted,
        target_host:    target.host,
        target_port:    target.port || 3306,
        target_user:    target.user,
        target_password:target.password,
        target_db:      target.db_name,
        create_db:      target.create_db,
        drop_existing:  target.drop_existing,
      });

      // Poll restore status
      const pollInterval = setInterval(async () => {
        try {
          const status = await r('GET', '/restore/status/' + res.restore_id);
          for (const log of (status.new_logs || [])) {
            addLog(log.level, log.message);
          }
          if (status.status === 'success') {
            clearInterval(pollInterval);
            addLog('SUCCESS', '✓ Database restored successfully!');
            addLog('INFO', 'Database "' + target.db_name + '" is ready on ' + target.host);
            setDone(true);
            setRestoring(false);
          } else if (status.status === 'failed') {
            clearInterval(pollInterval);
            addLog('ERROR', 'Restore failed: ' + status.error);
            setRestoring(false);
          }
        } catch {}
      }, 2000);

    } catch(e) {
      addLog('ERROR', 'Restore failed: ' + e.message);
      setRestoring(false);
    }
  }

  const LOG_COLORS = {
    INFO:    'var(--bv-txt2)',
    SUCCESS: 'var(--bv-green)',
    ERROR:   'var(--bv-red)',
    WARN:    'var(--bv-amber)',
  };

  return (
    <div style={{ flex:1, display:'flex', flexDirection:'column', overflow:'hidden' }}>

      {/* Header */}
      <div style={{ padding:'14px 22px 12px', borderBottom:'1px solid var(--bv-bd)',
        background:'var(--bv-bg2)', flexShrink:0 }}>
        <div style={{ fontSize:20, fontWeight:500, color:'var(--bv-txt)',
          display:'flex', alignItems:'center', gap:9 }}>
          <i className="ti ti-database-import" style={{ color:'var(--bv-blue)', fontSize:22 }}/>
          Database Restore
        </div>
        <div style={{ fontSize:12, color:'var(--bv-txt2)', marginTop:3 }}>
          Restore from any backup tier to any target server for DR purposes
        </div>

        {/* Step indicator */}
        <div style={{ display:'flex', gap:0, marginTop:14 }}>
          {STEPS.map((s, i) => (
            <div key={i} style={{ display:'flex', alignItems:'center' }}>
              <div style={{ display:'flex', alignItems:'center', gap:6,
                padding:'5px 14px', borderRadius:20, fontSize:12, fontWeight:500,
                background: step === i ? 'var(--bv-blue)' : i < step ? 'var(--bv-green-bg)' : 'var(--bv-bg3)',
                color: step === i ? '#fff' : i < step ? 'var(--bv-green)' : 'var(--bv-txt3)',
                border: '1px solid ' + (step === i ? 'var(--bv-blue)' : i < step ? 'var(--bv-green)' : 'var(--bv-bd)') }}>
                {i < step
                  ? <i className="ti ti-check" style={{ fontSize:12 }}/>
                  : <span style={{ fontSize:11, fontWeight:700 }}>{i+1}</span>}
                {s}
              </div>
              {i < STEPS.length - 1 && (
                <div style={{ width:24, height:1, background:'var(--bv-bd)', margin:'0 4px' }}/>
              )}
            </div>
          ))}
        </div>
      </div>

      <div style={{ flex:1, overflowY:'auto', padding:'20px 22px' }}>

        {/* ── STEP 0: SELECT TIER ── */}
        {step === 0 && (
          <div>
            <div style={{ fontSize:14, fontWeight:500, color:'var(--bv-txt)', marginBottom:14 }}>
              Select backup source tier:
            </div>
            <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill, minmax(280px, 1fr))', gap:14 }}>
              {TIERS.map(t => (
                <div key={t.key} onClick={() => selectTier(t)}
                  style={{ padding:'18px 20px', background:'var(--bv-card)',
                    border:'2px solid var(--bv-bd)', borderRadius:12, cursor:'pointer',
                    transition:'all .15s' }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = t.color; e.currentTarget.style.background = 'var(--bv-hover)'; }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--bv-bd)'; e.currentTarget.style.background = 'var(--bv-card)'; }}>
                  <div style={{ display:'flex', alignItems:'center', gap:12, marginBottom:8 }}>
                    <div style={{ width:40, height:40, borderRadius:10,
                      background:'var(--bv-bg3)', display:'flex', alignItems:'center',
                      justifyContent:'center' }}>
                      <i className={'ti ti-' + t.icon} style={{ fontSize:20, color:t.color }}/>
                    </div>
                    <div>
                      <div style={{ fontSize:14, fontWeight:600, color:'var(--bv-txt)' }}>{t.label}</div>
                      <div style={{ fontSize:11, color:'var(--bv-txt3)', marginTop:2 }}>{t.desc}</div>
                    </div>
                  </div>
                  {t.key === 'oci' && (
                    <span style={{ fontSize:10, padding:'2px 8px', borderRadius:8,
                      background:'var(--bv-green-bg)', color:'var(--bv-green)',
                      border:'1px solid var(--bv-green)', fontWeight:600 }}>
                      🔐 AES-256-GCM Encrypted
                    </span>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ── STEP 1: SELECT FILE ── */}
        {step === 1 && (
          <div>
            <div style={{ display:'flex', justifyContent:'space-between', marginBottom:14 }}>
              <div style={{ fontSize:14, fontWeight:500, color:'var(--bv-txt)' }}>
                Select backup file from <strong style={{ color:tier?.color || 'var(--bv-blue)' }}>{tier?.label}</strong>:
              </div>
              <Btn variant="ghost" size="sm" icon="arrow-left" onClick={() => setStep(0)}>Back</Btn>
            </div>

            {loadingFiles ? (
              <div style={{ display:'flex', gap:12, padding:40, justifyContent:'center', color:'var(--bv-txt3)' }}>
                <Spinner size={22}/> Loading backup files...
              </div>
            ) : files.length === 0 ? (
              <div style={{ textAlign:'center', padding:60, color:'var(--bv-txt3)' }}>
                <i className="ti ti-file-off" style={{ fontSize:40, display:'block', marginBottom:12, color:'var(--bv-bd2)' }}/>
                <div style={{ fontSize:14, color:'var(--bv-txt2)' }}>No backup files found</div>
              </div>
            ) : (
              <div style={{ background:'var(--bv-card)', border:'1px solid var(--bv-bd)',
                borderRadius:10, overflow:'hidden' }}>
                <div style={{ display:'grid', gridTemplateColumns:'1fr 100px 160px 120px',
                  padding:'8px 16px', background:'var(--bv-bg3)',
                  borderBottom:'1px solid var(--bv-bd)',
                  fontSize:10, fontWeight:600, color:'var(--bv-txt3)',
                  textTransform:'uppercase', letterSpacing:'.06em' }}>
                  <span>File Name</span><span>Size</span><span>Date</span><span>Action</span>
                </div>
                {files.map((f, i) => (
                  <div key={i} style={{ display:'grid',
                    gridTemplateColumns:'1fr 100px 160px 120px',
                    padding:'10px 16px', borderBottom:'1px solid var(--bv-bd)',
                    alignItems:'center' }}>
                    <div style={{ display:'flex', alignItems:'center', gap:8 }}>
                      <i className="ti ti-file-zip" style={{ color:'var(--bv-blue)', fontSize:16 }}/>
                      <div>
                        <div style={{ fontSize:12, color:'var(--bv-txt)', fontFamily:'monospace' }}>{f.name}</div>
                        {f.encrypted && (
                          <span style={{ fontSize:10, padding:'1px 6px', borderRadius:5,
                            background:'var(--bv-green-bg)', color:'var(--bv-green)',
                            border:'1px solid var(--bv-green)', fontWeight:600 }}>
                            🔐 AES-256-GCM
                          </span>
                        )}
                      </div>
                    </div>
                    <span style={{ fontSize:12, color:'var(--bv-txt2)' }}>{fmtBytes(f.size)}</span>
                    <span style={{ fontSize:11, color:'var(--bv-txt3)' }}>{fmtDate(f.modified)}</span>
                    <Btn variant="primary" size="sm" onClick={() => selectFile(f)}>
                      Select
                    </Btn>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* ── STEP 2: TARGET SERVER ── */}
        {step === 2 && (
          <div style={{ maxWidth:560 }}>
            <div style={{ display:'flex', justifyContent:'space-between', marginBottom:16 }}>
              <div style={{ fontSize:14, fontWeight:500, color:'var(--bv-txt)' }}>
                Configure restore target server:
              </div>
              <Btn variant="ghost" size="sm" icon="arrow-left" onClick={() => setStep(1)}>Back</Btn>
            </div>

            {/* Selected file info */}
            <div style={{ padding:'10px 14px', background:'var(--bv-bg3)',
              border:'1px solid var(--bv-bd)', borderRadius:8, marginBottom:16,
              fontSize:12, color:'var(--bv-txt2)' }}>
              <strong>Restoring:</strong> <span style={{ fontFamily:'monospace', color:'var(--bv-cyan)' }}>{selectedFile?.name}</span>
              <span style={{ marginLeft:12, color:'var(--bv-txt3)' }}>from {tier?.label}</span>
              {selectedFile?.encrypted && (
                <span style={{ marginLeft:12, color:'var(--bv-green)', fontWeight:600 }}>🔐 Will decrypt with BACKUP_ENCRYPTION_KEY</span>
              )}
            </div>

            {/* Quick fill from existing servers */}
            {dbServers.length > 0 && (
              <Field label="Quick fill from existing DB server (optional)">
                <select onChange={e => {
                  const s = dbServers.find(x => String(x.id) === e.target.value);
                  if (s) setTarget(p => ({ ...p, host:s.host, port:s.port||3306, user:s.username||'root' }));
                }} style={{ width:'100%' }}>
                  <option value="">Select a server...</option>
                  {dbServers.map(s => (
                    <option key={s.id} value={s.id}>{s.name} ({s.host})</option>
                  ))}
                </select>
              </Field>
            )}

            <div style={{ display:'grid', gridTemplateColumns:'1fr 120px', gap:'0 12px' }}>
              <Field label="Target Host / IP" required>
                <input value={target.host} onChange={e => setTarget(p => ({...p, host:e.target.value}))}
                  placeholder="10.180.0.100 or new-server-ip" style={{ width:'100%' }} required/>
              </Field>
              <Field label="Port">
                <input type="number" value={target.port} onChange={e => setTarget(p => ({...p, port:e.target.value}))}
                  style={{ width:'100%' }}/>
              </Field>
            </div>

            <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:'0 12px' }}>
              <Field label="MySQL Username" required>
                <input value={target.user} onChange={e => setTarget(p => ({...p, user:e.target.value}))}
                  placeholder="root" style={{ width:'100%' }} required/>
              </Field>
              <Field label="MySQL Password">
                <input type="password" value={target.password}
                  onChange={e => setTarget(p => ({...p, password:e.target.value}))}
                  style={{ width:'100%' }}/>
              </Field>
            </div>

            <Field label="Target Database Name" required hint="Database will be created if it doesn't exist">
              <input value={target.db_name} onChange={e => setTarget(p => ({...p, db_name:e.target.value}))}
                placeholder="wtms_restore" style={{ width:'100%' }} required/>
            </Field>

            <div style={{ display:'flex', gap:16, padding:'10px 14px',
              background:'var(--bv-bg3)', borderRadius:8, marginBottom:16 }}>
              <label style={{ display:'flex', alignItems:'center', gap:8, cursor:'pointer', fontSize:12 }}>
                <input type="checkbox" checked={target.create_db}
                  onChange={e => setTarget(p => ({...p, create_db:e.target.checked}))}/>
                Create database if not exists
              </label>
              <label style={{ display:'flex', alignItems:'center', gap:8, cursor:'pointer', fontSize:12 }}>
                <input type="checkbox" checked={target.drop_existing}
                  onChange={e => setTarget(p => ({...p, drop_existing:e.target.checked}))}/>
                <span style={{ color: target.drop_existing ? 'var(--bv-red)' : 'inherit' }}>
                  Drop existing tables first
                </span>
              </label>
            </div>

            <Btn variant="primary" icon="database-import"
              disabled={!target.host || !target.db_name}
              onClick={() => { setStep(3); startRestore(); }}>
              Start Restore
            </Btn>
          </div>
        )}

        {/* ── STEP 3: RESTORE LOG ── */}
        {step === 3 && (
          <div>
            <div style={{ display:'flex', justifyContent:'space-between', marginBottom:14 }}>
              <div style={{ fontSize:14, fontWeight:500, color:'var(--bv-txt)',
                display:'flex', alignItems:'center', gap:8 }}>
                {restoring
                  ? <><Spinner size={16}/> Restoring...</>
                  : done
                    ? <><i className="ti ti-check" style={{ color:'var(--bv-green)' }}/> Restore Complete</>
                    : <><i className="ti ti-x" style={{ color:'var(--bv-red)' }}/> Restore Failed</>}
              </div>
              {!restoring && (
                <Btn variant="ghost" size="sm" onClick={() => { setStep(0); setTier(null); setSelectedFile(null); setRestoreLog([]); setDone(false); }}>
                  New Restore
                </Btn>
              )}
            </div>

            {/* Restore terminal log */}
            <div style={{ background:'#0d1117', borderRadius:10,
              border:'1px solid var(--bv-bd)', padding:'12px 16px',
              fontFamily:'monospace', fontSize:12, lineHeight:1.8,
              minHeight:300, maxHeight:500, overflowY:'auto' }}>
              {restoreLog.map((l, i) => (
                <div key={i} style={{ display:'flex', gap:14 }}>
                  <span style={{ color:'#555', flexShrink:0, fontSize:11 }}>{l.time}</span>
                  <span style={{ color: LOG_COLORS[l.level] || LOG_COLORS.INFO,
                    fontWeight: l.level === 'SUCCESS' || l.level === 'ERROR' ? 600 : 400 }}>
                    [{l.level}]
                  </span>
                  <span style={{ color: l.level==='SUCCESS'?'#69db7c':l.level==='ERROR'?'#ff6b6b':l.level==='WARN'?'#ffd43b':'#c9d1d9' }}>
                    {l.msg}
                  </span>
                </div>
              ))}
              {restoring && (
                <div style={{ color:'var(--bv-txt3)', marginTop:8 }}>
                  <Spinner size={12}/> <span style={{ marginLeft:6 }}>Processing...</span>
                </div>
              )}
            </div>

            {done && (
              <div style={{ marginTop:14, padding:'12px 16px',
                background:'var(--bv-green-bg)', border:'1px solid var(--bv-green)',
                borderRadius:8, fontSize:13, color:'var(--bv-green)' }}>
                <i className="ti ti-circle-check" style={{ marginRight:8 }}/>
                <strong>Database restored successfully.</strong>
                {' '}You can now connect to <code>{target.db_name}</code> on <code>{target.host}:{target.port}</code>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
